              fixedCode: "#include <iostream>\nclass Holder {\n public:\n  Holder() : p(new int(42)) {}\n  Holder(const Holder& o) : p(new int(*o.p)) {}\n  Holder& operator=(const Holder& o) {\n    if (this != &o) { delete p; p = new int(*o.p); }\n    return *this;\n  }\n  ~Holder() { delete p; }\n  int get() const { return *p; }\n private:\n  int* p;\n};\nint main() {\n  Holder a;\n  Holder b = a;\n  std::cout << b.get() << \"\\n\";\n}",
