            syntax: "asio::io_context io; asio::ip::tcp::socket sock(io);",
            exampleCode: "#include <arpa/inet.h>\n#include <iostream>\n#include <netdb.h>\n#include <string>\n\nint main() {\n  addrinfo hints{};\n  hints.ai_family = AF_INET;\n  hints.ai_socktype = SOCK_STREAM;\n  addrinfo* res = nullptr;\n  if (getaddrinfo(\"localhost\", \"8080\", &hints, &res) != 0) { std::cout << \"resolve failed\\n\"; return 0; }\n  char buf[INET_ADDRSTRLEN];\n  auto* addr = reinterpret_cast<sockaddr_in*>(res->ai_addr);\n  inet_ntop(AF_INET, &addr->sin_addr, buf, sizeof(buf));\n  std::cout << \"localhost resolves to \" << buf << \":\" << ntohs(addr->sin_port) << \"\\n\";\n  freeaddrinfo(res);\n}\n",
